package com.hellodoc.controller;
import com.hellodoc.dto.*; import com.hellodoc.service.DoctorProfileService; import com.hellodoc.service.AppointmentService; import com.hellodoc.service.ReviewService; import jakarta.validation.Valid; import org.springframework.data.domain.Page; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.time.Instant; import java.util.UUID;
@RestController @RequestMapping("/api/doctors") public class DoctorController {
 private final DoctorProfileService doctors; private final AppointmentService appointments; private final ReviewService reviews; public DoctorController(DoctorProfileService doctors,AppointmentService appointments,ReviewService reviews){this.doctors=doctors;this.appointments=appointments;this.reviews=reviews;}
 @GetMapping @PreAuthorize("permitAll()") public Page<DoctorSearchDto> search(@RequestParam(required=false) String q,@RequestParam(required=false) String specialty,@RequestParam(required=false) String city,@RequestParam(required=false) String availableOn,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){LocalDate date=availableOn==null||availableOn.isBlank()?null:LocalDate.parse(availableOn);return doctors.search(q,specialty,city,date,page,size);}
 @GetMapping("/{id}") @PreAuthorize("permitAll()") public DoctorPublicDto publicProfile(@PathVariable UUID id){return doctors.publicProfile(id);}
 @GetMapping("/{id}/slots") @PreAuthorize("permitAll()") public java.util.List<TimeSlotDto> slots(@PathVariable UUID id,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate date){return appointments.freeSlots(id,date);}
 @GetMapping("/{id}/availability-calendar") @PreAuthorize("permitAll()") public java.util.List<AvailabilityCalendarDayDto> availabilityCalendar(@PathVariable UUID id,@RequestParam String month){try{return doctors.calendar(id,java.time.YearMonth.parse(month));}catch(java.time.format.DateTimeParseException ex){throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST,"Le mois doit respecter le format YYYY-MM.");}}
 @GetMapping("/me") @PreAuthorize("hasRole('DOCTOR')") public DoctorProfileDto me(Authentication auth){return doctors.ownProfile(auth.getName());}
 @GetMapping("/me/dashboard") @PreAuthorize("hasRole('DOCTOR')") public DoctorDashboardDto dashboard(Authentication auth){return appointments.doctorDashboard(auth.getName());}
 @GetMapping("/me/appointments") @PreAuthorize("hasRole('DOCTOR')") public PagedResponse<AppointmentDto> appointments(Authentication auth,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) Instant from,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) Instant to,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="100") int size){return appointments.doctorAppointments(auth.getName(),from,to,page,size);}
 @GetMapping("/me/reviews") @PreAuthorize("hasRole('DOCTOR')") public PagedResponse<ReviewDto> reviews(Authentication auth,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="50") int size){return reviews.doctorReviews(auth.getName(),page,size);}
 @PutMapping("/me") @PreAuthorize("hasRole('DOCTOR')") public DoctorProfileDto update(Authentication auth,@Valid @RequestBody DoctorProfileUpdateRequest request){return doctors.update(auth.getName(),request);}
 @GetMapping("/me/availabilities") @PreAuthorize("hasRole('DOCTOR')") public java.util.List<AvailabilityDto> availabilities(Authentication auth){return doctors.listAvailabilities(auth.getName());}
 @PostMapping("/me/availabilities") @PreAuthorize("hasRole('DOCTOR')") @ResponseStatus(org.springframework.http.HttpStatus.CREATED) public AvailabilityDto addAvailability(Authentication auth,@Valid @RequestBody AvailabilityRequest request){return doctors.addAvailability(auth.getName(),request);}
 @PutMapping("/me/availabilities/weekly") @PreAuthorize("hasRole('DOCTOR')") public java.util.List<AvailabilityDto> replaceWeeklyAvailability(Authentication auth,@Valid @RequestBody WeeklyAvailabilityRequest request){return doctors.replaceWeeklyAvailability(auth.getName(),request);}
 @PutMapping("/me/availabilities/{id}") @PreAuthorize("hasRole('DOCTOR')") public AvailabilityDto updateAvailability(Authentication auth,@PathVariable UUID id,@Valid @RequestBody AvailabilityRequest request){return doctors.updateAvailability(auth.getName(),id,request);}
 @DeleteMapping("/me/availabilities/{id}") @PreAuthorize("hasRole('DOCTOR')") @ResponseStatus(org.springframework.http.HttpStatus.NO_CONTENT) public void deleteAvailability(Authentication auth,@PathVariable UUID id){doctors.deleteAvailability(auth.getName(),id);}
}
